mapper.select:
select tb.* from Tran_Basic tb,issue_info io where tb.cusip=io.cusip and tb.cusip is not null and  tb.portfolio in

	#{item}



		and tb.tradedate>=#{startDate}




		and tb.tradedate<=#{endDate}




		and io.issueType=#{secType}




		and io.securityid=#{secID}




		and tb.post_Status<>'D'


order by tradedate desc, tanum desc
